"use client";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";

function getBreadcrumbItems(pathname: string, recipeTitle?: string) {
  const segments = pathname.split("/").filter(Boolean);

  const items = [{ title: "Thrive", href: "/" }];

  if (segments.length > 0) {
    items.push({ title: "Dashboard", href: "/dashboard" });

    if (segments.length > 1) {
      const routeName = segments[1];

      // Handle recipe routes specially
      if (routeName === "recipe" && segments.length > 2) {
        // Add recipe explorer
        items.push({
          title: "Recipe Explorer",
          href: "/dashboard/recipe-explorer",
        });

        // Add the specific recipe name
        const recipeName = recipeTitle || "Recipe";
        items.push({ title: recipeName, href: pathname });
      } else {
        // Handle other routes
        const formattedName = routeName
          .split("-")
          .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
          .join(" ");

        items.push({ title: formattedName, href: pathname });
      }
    }
  }

  return items;
}

export default function BreadcrumbWrapper() {
  const pathname = usePathname();
  const [recipeTitle, setRecipeTitle] = useState<string>();

  // Fetch recipe title if we're on a recipe page
  useEffect(() => {
    const segments = pathname.split("/").filter(Boolean);
    if (segments[1] === "recipe" && segments[2]) {
      const recipeId = segments[2];

      // Fetch recipe details to get the title
      fetch(`/api/recipes/${recipeId}`)
        .then((res) => res.json())
        .then((data) => {
          setRecipeTitle(data.title);
        })
        .catch((err) => {
          console.error("Failed to fetch recipe title:", err);
          setRecipeTitle("Recipe");
        });
    }
  }, [pathname]);

  const breadcrumbItems = getBreadcrumbItems(pathname, recipeTitle);

  return (
    <Breadcrumb>
      <BreadcrumbList>
        {breadcrumbItems.map((item, index) => (
          <div key={item.href} className="flex items-center">
            <BreadcrumbItem className={index === 0 ? "hidden md:block" : ""}>
              {index === breadcrumbItems.length - 1 ? (
                <BreadcrumbPage>{item.title}</BreadcrumbPage>
              ) : (
                <BreadcrumbLink href={item.href}>{item.title}</BreadcrumbLink>
              )}
            </BreadcrumbItem>
            {index < breadcrumbItems.length - 1 && (
              <BreadcrumbSeparator
                className={index === 0 ? "hidden md:block" : ""}
              />
            )}
          </div>
        ))}
      </BreadcrumbList>
    </Breadcrumb>
  );
}

"use client";

import { MealDetailModal } from "@/components/dashboard/MealDetailModal";
import { MealSwapModal } from "@/components/dashboard/MealSwapModal";
import {
  MealPlanHeader,
  DateNavigation,
  WeeklyStatsCard,
  DailyStatsCard,
  WeeklyMealGrid,
  DailyMealGrid,
  useMealPlanData,
  type MealPlanItem,
} from "@/components/dashboard/meal-plans";
import type React from "react";
import { useState } from "react";

const dailyStats = {
  totalCalories: 1550,
  caloriesLeft: 450,
  protein: 110,
  carbs: 135,
  fat: 55,
  goal: 2000,
};

export default function MealPlansPage() {
  const {
    viewMode,
    currentDate,
    currentDayIndex, // Add currentDayIndex here
    weeklyMeals,
    draggedItem,
    activeDropZone,
    sampleMeals,
    weeklyStats,
    isLoading,
    setViewMode,
    setDraggedItem,
    setActiveDropZone,
    navigateDate,
    updateSingleMeal,
    swapMeals,
  } = useMealPlanData();

  const [swapModalOpen, setSwapModalOpen] = useState(false);
  const [swapMealType, setSwapMealType] = useState<string>("");
  const [swapDayIndex, setSwapDayIndex] = useState<number>(0);
  const [recipeDetailOpen, setRecipeDetailOpen] = useState(false);
  const [selectedRecipe, setSelectedRecipe] = useState<MealPlanItem | null>(
    null
  );
  const [selectedMealType, setSelectedMealType] = useState<string>("");

  const handleRegenerate = () => {
    // TODO: Implement regenerate logic
    console.log("Regenerating meal plan...");
  };

  const handleSwapClick = (mealType: string, dayIndex?: number) => {
    setSwapMealType(mealType);
    // Use nullish coalescing so a dayIndex of 0 is preserved
    setSwapDayIndex(dayIndex ?? 0);
    setSwapModalOpen(true);
  };

  const handleRecipeSelect = (recipe: MealPlanItem) => {
    // Guard: ensure a swap target was selected
    if (!swapMealType) {
      console.warn(
        "handleRecipeSelect called but swapMealType is empty. Aborting."
      );
      setSwapModalOpen(false);
      return;
    }

    // Use the new updateSingleMeal function for better persistence
    updateSingleMeal(swapDayIndex, swapMealType, recipe);
    setSwapModalOpen(false);
  };

  const handleRecipeClick = (
    recipe: MealPlanItem,
    mealType: string,
    dayIndex?: number
  ) => {
    setSelectedRecipe(recipe);
    setSelectedMealType(mealType);
    if (dayIndex !== undefined) {
      setSwapDayIndex(dayIndex);
    }
    setRecipeDetailOpen(true);
  };

  const handleDeleteMeal = () => {
    // remove the selectedRecipe from weeklyMeals using selectedMealType and swapDayIndex
    if (!selectedRecipe) return;

    // Use the new updateSingleMeal function to remove the meal
    updateSingleMeal(swapDayIndex, selectedMealType, null);

    // close modal
    setRecipeDetailOpen(false);
    setSelectedRecipe(null);
  };

  const handleEmptySlotClick = (mealType: string, dayIndex: number) => {
    // Open the swap modal to let user fill the empty slot
    setSwapMealType(mealType);
    setSwapDayIndex(dayIndex);
    setSwapModalOpen(true);
  };

  const handleDragStart = (
    e: React.DragEvent,
    meal: MealPlanItem,
    mealType: string,
    dayIndex: number
  ) => {
    setDraggedItem({ meal, mealType, dayIndex });
    e.dataTransfer.setData("mealId", meal.id.toString());
    e.dataTransfer.setData("mealType", mealType);
    e.dataTransfer.setData("dayIndex", dayIndex.toString());
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragEnd = () => {
    setDraggedItem(null);
    setActiveDropZone(null);
  };

  const handleDragOver = (
    e: React.DragEvent,
    mealType: string,
    dayIndex: number
  ) => {
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = "move";

    if (
      draggedItem &&
      (draggedItem.mealType !== mealType || draggedItem.dayIndex !== dayIndex)
    ) {
      setActiveDropZone({ mealType, dayIndex });
    }
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const isInside =
      e.clientX >= rect.left &&
      e.clientX <= rect.right &&
      e.clientY >= rect.top &&
      e.clientY <= rect.bottom;

    if (!isInside) {
      setActiveDropZone(null);
    }
  };

  const handleDrop = (
    e: React.DragEvent,
    targetMealType: string,
    targetDayIndex: number
  ) => {
    e.preventDefault();
    e.stopPropagation();

    if (!draggedItem) return;

    if (
      draggedItem.dayIndex === targetDayIndex &&
      draggedItem.mealType === targetMealType
    ) {
      setDraggedItem(null);
      setActiveDropZone(null);
      return;
    }

    const sourceDayIndex = draggedItem.dayIndex;
    const sourceMealType = draggedItem.mealType;

    setDraggedItem(null);
    setActiveDropZone(null);

    // Use the new swapMeals function for better persistence
    swapMeals(sourceDayIndex, sourceMealType, targetDayIndex, targetMealType);
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      {isLoading ? (
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
          <span className="ml-3 text-gray-600">Loading your meal plan...</span>
        </div>
      ) : (
        <>
          <MealPlanHeader
            viewMode={viewMode}
            onViewModeChange={setViewMode}
            onRegenerate={handleRegenerate}
          />

          <DateNavigation
            viewMode={viewMode}
            currentDate={currentDate}
            onNavigate={navigateDate}
          />

          {viewMode === "weekly" ? (
            <>
              <WeeklyStatsCard stats={weeklyStats} />
              <WeeklyMealGrid
                weeklyMeals={weeklyMeals}
                draggedItem={draggedItem}
                activeDropZone={activeDropZone}
                onDragStart={handleDragStart}
                onDragEnd={handleDragEnd}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                onRecipeClick={handleRecipeClick}
                currentDayIndex={currentDayIndex}
                onEmptySlotClick={handleEmptySlotClick}
              />
            </>
          ) : (
            <>
              <DailyStatsCard stats={dailyStats} />
              <DailyMealGrid
                sampleMeals={sampleMeals}
                onRecipeClick={handleRecipeClick}
                weeklyMeals={weeklyMeals}
                onEmptySlotClick={handleEmptySlotClick}
                currentDayIndex={currentDayIndex}
              />
            </>
          )}
        </>
      )}

      <MealDetailModal
        isOpen={recipeDetailOpen}
        onClose={() => setRecipeDetailOpen(false)}
        meal={selectedRecipe}
        mealType={selectedMealType}
        dayIndex={swapDayIndex}
        onSwapClick={handleSwapClick}
        onDelete={handleDeleteMeal}
      />

      <MealSwapModal
        isOpen={swapModalOpen}
        onClose={() => setSwapModalOpen(false)}
        mealType={swapMealType}
        availableMeals={
          sampleMeals[swapMealType.toLowerCase() as keyof typeof sampleMeals] ||
          []
        }
        onMealSelect={handleRecipeSelect}
      />
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "framer-motion";
import { useEffect, useRef, useState, useCallback } from "react";
import { useUser } from "@clerk/nextjs";
import { useRouter } from "next/navigation";
import { Citrus } from "lucide-react";
import { SignOutButton } from "@clerk/nextjs";

type QuestionType = "number" | "single-choice" | "multi-choice";

interface Question {
  id: number;
  question: string;
  name: keyof FormDataState;
  type: QuestionType;
  options?: string[];
}

interface FormDataState {
  age?: number;
  weight?: number;
  height?: number;
  fitnessGoal?: string;
  activityLevel?: string;
  dietType?: string;
}

const questions: Question[] = [
  { id: 1, question: "What's your age?", name: "age", type: "number" },
  {
    id: 2,
    question: "What's your weight (kg)?",
    name: "weight",
    type: "number",
  },
  {
    id: 3,
    question: "What's your height (cm)?",
    name: "height",
    type: "number",
  },
  {
    id: 4,
    question: "What's your main fitness goal?",
    name: "fitnessGoal",
    type: "single-choice",
    options: [
      "Lose Weight",
      "Build Muscle",
      "Improve Endurance",
      "Stay Healthy",
    ],
  },
  {
    id: 5,
    question: "What's your activity level?",
    name: "activityLevel",
    type: "single-choice",
    options: [
      "Sedentary",
      "Lightly Active",
      "Moderately Active",
      "Very Active",
    ],
  },
  {
    id: 6,
    question: "What type of diet do you follow?",
    name: "dietType",
    type: "single-choice",
    options: ["Vegetarian", "Non-Vegetarian", "Vegan", "Pescatarian"],
  },
];

export default function OnboardingPage() {
  const { user } = useUser();
  const router = useRouter();
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<FormDataState>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const currentQuestion = questions[step];
  const inputRef = useRef<HTMLInputElement | null>(null);

  const handleSubmit = useCallback(async () => {
    if (!user) {
      console.error("No user found");
      return;
    }

    setIsSubmitting(true);

    try {
      const userData = {
        clerkId: user.id,
        email: user.emailAddresses[0]?.emailAddress || "",
        name: user.fullName || user.firstName || "",
        age: formData.age,
        weight: formData.weight,
        goals: formData.fitnessGoal,
        allergies: [formData.dietType || "Non-Vegetarian"],
        activityLevel: formData.activityLevel,
        height: formData.height,
      };

      const response = await fetch("/api/users", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(userData),
      });

      if (!response.ok) {
        throw new Error("Failed to save user data");
      }

      const savedUser = await response.json();
      console.log("User saved successfully:", savedUser);

      // Redirect to dashboard after successful save
      router.push("/dashboard");
    } catch (error) {
      console.error("Failed to save user:", error);
      alert("Failed to save your information. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  }, [user, formData, router]);

  const handleNext = useCallback(() => {
    if (step < questions.length - 1) {
      setStep(step + 1);
    } else {
      handleSubmit();
    }
  }, [step, handleSubmit]);

  const handlePrev = useCallback(() => {
    if (step > 0) setStep(step - 1);
  }, [step]);

  const isAnswered = (q: Question): boolean => {
    const val = formData[q.name];
    if (q.type === "number") return typeof val === "number" && val > 0;
    if (q.type === "single-choice")
      return typeof val === "string" && val !== "";
    if (q.type === "multi-choice") return Array.isArray(val) && val.length > 0;
    return false;
  };

  // ✅ Always focus numeric inputs after step change (with slight delay for animation)
  useEffect(() => {
    if (currentQuestion.type === "number") {
      const timer = setTimeout(() => {
        if (inputRef.current) {
          inputRef.current.focus();
          inputRef.current.select();
        }
      }, 350); // matches motion animation timing
      return () => clearTimeout(timer);
    }
  }, [step, currentQuestion]);

  // Global keyboard handling
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (isSubmitting) return; // Disable keyboard during submission

      const num = Number(e.key);

      if (
        (currentQuestion.type === "single-choice" ||
          currentQuestion.type === "multi-choice") &&
        Number.isInteger(num) &&
        num >= 1 &&
        num <= (currentQuestion.options?.length || 0)
      ) {
        const selectedOption = currentQuestion.options![num - 1];
        setFormData((prev) => {
          if (currentQuestion.type === "single-choice") {
            const already = prev[currentQuestion.name] === selectedOption;
            return {
              ...prev,
              [currentQuestion.name]: already ? undefined : selectedOption,
            };
          }
          // Multi-choice logic commented out since we only have single-choice questions now
          return prev;
        });
      }

      if (e.key === "Enter" || e.key === "NumpadEnter") {
        e.preventDefault();
        const val = formData[currentQuestion.name];
        let answered = false;
        if (currentQuestion.type === "number")
          answered = typeof val === "number" && val > 0;
        else if (currentQuestion.type === "single-choice")
          answered = typeof val === "string" && val !== "";
        else if (currentQuestion.type === "multi-choice")
          answered = Array.isArray(val) && val.length > 0;

        if (answered) handleNext();
      }

      if ((e.metaKey || e.ctrlKey) && e.key === "ArrowRight") {
        e.preventDefault();
        handleNext();
      }
      if ((e.metaKey || e.ctrlKey) && e.key === "ArrowLeft") {
        e.preventDefault();
        handlePrev();
      }
    };

    window.addEventListener("keydown", handleKey);
    return () => window.removeEventListener("keydown", handleKey);
  }, [step, currentQuestion, formData, isSubmitting, handleNext, handlePrev]);

  if (isSubmitting) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-50 to-blue-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto mb-4"></div>
          <p className="text-lg font-medium text-gray-700">
            Setting up your profile...
          </p>
        </div>
      </div>
    );
  }

  return (
    <section className="mx-auto min-h-screen max-w-7xl p-5 flex flex-col bg-gradient-to-br from-green-50 to-blue-50">
      {/* Navbar */}
      <nav className="flex justify-between items-center h-16">
        <div className="flex flex-row items-center">
          <div className="m-2 rounded-md bg-green-600 p-1 shadow-md">
            <Citrus color="white" strokeWidth={1.5} />
          </div>
          <h1 className="text-xl font-semibold">Thrive AI</h1>
        </div>
        <SignOutButton>
          <button className="bg-red-500 text-white rounded-full px-4 py-2 text-sm hover:bg-red-600">
            Sign Out
          </button>
        </SignOutButton>
      </nav>

      {/* Progress Bar */}
      <div className="mb-8">
        <div className="flex justify-between text-xs text-gray-500 mb-2">
          <span>
            Step {step + 1} of {questions.length}
          </span>
          <span>
            {Math.round(((step + 1) / questions.length) * 100)}% Complete
          </span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className="bg-green-600 h-2 rounded-full transition-all duration-300"
            style={{ width: `${((step + 1) / questions.length) * 100}%` }}
          ></div>
        </div>
      </div>

      {/* Progressive Form */}
      <main className="flex flex-1 items-center justify-center">
        <div className="w-full max-w-xl">
          <AnimatePresence mode="wait">
            <motion.div
              key={currentQuestion.id}
              initial={{ opacity: 0, x: 50 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -50 }}
              transition={{ duration: 0.3 }}
              className="w-full bg-white rounded-lg shadow-lg p-8"
            >
              <h2 className="text-2xl font-semibold mb-6 text-gray-800">
                {currentQuestion.question}
              </h2>

              {currentQuestion.type === "number" && (
                <input
                  ref={inputRef}
                  type="number"
                  min={1}
                  className="w-full border border-gray-300 rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-green-600 text-lg"
                  value={formData[currentQuestion.name] ?? ""}
                  onChange={(e) =>
                    setFormData((prev) => ({
                      ...prev,
                      [currentQuestion.name]: e.target.value
                        ? Math.max(1, Number(e.target.value))
                        : undefined,
                    }))
                  }
                  placeholder="Enter a value"
                />
              )}

              {currentQuestion.type === "single-choice" && (
                <div className="flex flex-col gap-3">
                  {currentQuestion.options!.map((opt, idx) => (
                    <div
                      key={opt}
                      onClick={() =>
                        setFormData((prev) => ({
                          ...prev,
                          [currentQuestion.name]:
                            prev[currentQuestion.name] === opt
                              ? undefined
                              : opt,
                        }))
                      }
                      className={`px-4 py-3 border rounded-lg cursor-pointer transition ${
                        formData[currentQuestion.name] === opt
                          ? "bg-green-600 text-white border-green-600"
                          : "border-gray-300 hover:bg-gray-50 hover:border-green-300"
                      }`}
                    >
                      {idx + 1}. {opt}
                    </div>
                  ))}
                  <p className="text-sm text-gray-500 mt-2">
                    Press 1, 2, 3... to select/unselect. Press Enter to
                    continue.
                  </p>
                </div>
              )}

              {/* Multi-choice logic commented out since we only have single-choice questions now
              {currentQuestion.type === "multi-choice" && (
                <div className="flex flex-col gap-3">
                  {currentQuestion.options!.map((opt, idx) => {
                    const arr =
                      (formData[currentQuestion.name] as string[]) || [];
                    return (
                      <div
                        key={opt}
                        onClick={() =>
                          setFormData((prev) => {
                            const already = arr.includes(opt);
                            return {
                              ...prev,
                              [currentQuestion.name]: already
                                ? arr.filter((v) => v !== opt)
                                : [...arr, opt],
                            };
                          })
                        }
                        className={`px-4 py-3 border rounded-lg cursor-pointer transition ${
                          arr.includes(opt)
                            ? "bg-green-600 text-white border-green-600"
                            : "border-gray-300 hover:bg-gray-50 hover:border-green-300"
                        }`}
                      >
                        {idx + 1}. {opt}
                      </div>
                    );
                  })}
                  <p className="text-sm text-gray-500 mt-2">
                    Press 1, 2, 3... to toggle options. Press Enter to continue.
                  </p>
                </div>
              )}
              */}

              {/* Navigation */}
              <div className="flex justify-between mt-8">
                <button
                  onClick={handlePrev}
                  disabled={step === 0}
                  className="px-6 py-2 rounded-lg border border-gray-300 text-gray-600 disabled:opacity-50 hover:bg-gray-50"
                >
                  Back
                </button>
                <button
                  onClick={handleNext}
                  disabled={!isAnswered(currentQuestion)}
                  className="px-6 py-2 rounded-lg bg-green-600 text-white disabled:opacity-50 hover:bg-green-700 font-medium"
                >
                  {step === questions.length - 1 ? "Complete Setup" : "Next"}
                </button>
              </div>
            </motion.div>
          </AnimatePresence>
        </div>
      </main>
    </section>
  );
}

"use client";

import { ArrowLeft } from "lucide-react";
import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";

import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { RecipeDetailsHeader } from "@/components/recipe/RecipeDetailsHeader";
import { RecipeIngredients } from "@/components/recipe/RecipeIngredients";
import { RecipeInstructions } from "@/components/recipe/RecipeInstructions";
import { RecipeVideoSection } from "@/components/recipe/RecipeVideoSection";

interface RecipeDetails {
  id: number;
  title: string;
  image: string;
  readyInMinutes: number;
  servings: number;
  dishTypes: string[];
  cuisines?: string[];
  diets?: string[];
  nutrition: {
    nutrients: Array<{
      name: string;
      amount: number;
      unit: string;
    }>;
  };
  extendedIngredients: Array<{
    id: number;
    name: string;
    amount: number;
    unit: string;
    image: string;
    original: string;
  }>;
  analyzedInstructions: Array<{
    name?: string;
    steps: Array<{
      number: number;
      step: string;
      equipment?: Array<{
        id: number;
        name: string;
      }>;
      ingredients?: Array<{
        id: number;
        name: string;
      }>;
    }>;
  }>;
  summary: string;
  sourceUrl?: string;
  spoonacularSourceUrl?: string;
}

interface VideoResult {
  title: string;
  youTubeId: string;
  rating: number;
  thumbnail: string;
}

export default function RecipePage() {
  const params = useParams();
  const router = useRouter();
  const recipeId = params.id as string;

  const [recipe, setRecipe] = useState<RecipeDetails | null>(null);
  const [videos, setVideos] = useState<VideoResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchRecipeDetails = async () => {
      try {
        setLoading(true);
        setError(null);

        const response = await fetch(`/api/recipes/${recipeId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch recipe: ${response.statusText}`);
        }

        const data = await response.json();
        console.log("Recipe data received:", data);
        setRecipe(data);
      } catch (error) {
        console.error("Error fetching recipe:", error);
        setError(
          error instanceof Error ? error.message : "Failed to fetch recipe"
        );
      } finally {
        setLoading(false);
      }
    };

    const fetchRecipeVideos = async () => {
